import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int max = Integer.MIN_VALUE;
        int min = Integer.MAX_VALUE;
        int count = 0;
        int sum = 0;

        for (int i = 0; i < 10; i++) {
            int num = sc.nextInt();
            if (num > max) max = num;
            if (num < min) min = num;
            if (num % 2 == 0) {
                count++;
                sum += num;
            }
        }

        double avg = count == 0 ? 0.0 : (double) sum / count;
        System.out.println("最大值是" + max);
        System.out.println("最小值是" + min);
        System.out.println("偶数的个数是" + count);
        System.out.println("偶数的平均值是" + avg);
    }
}

import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double[] amounts = new double[5];
        double total = 0;

        for (int i = 0; i < 5; i++) {
            amounts[i] = sc.nextDouble();
            total += amounts[i];
        }

        System.out.println("序号            金额");
        for (int i = 0; i < 5; i++) {
            System.out.println((i + 1) + "            ¥ " + amounts[i]);
        }
        System.out.println("----------------------");
        System.out.println("消费总金额：    ¥ " + (int) total);
    }
}

public class Main {
    public static void main(String[] args) {
        int[][] a = new int[10][10];
        System.out.println("杨辉三角形");

        for (int i = 0; i < 10; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0 || j == i) {
                    a[i][j] = 1;
                } else {
                    a[i][j] = a[i - 1][j - 1] + a[i - 1][j];
                }
                System.out.print(a[i][j] + "  ");
            }
            System.out.println();
        }
    }
}
